import {cloud} from './cloud.js';
import {icon,brand,atlas} from './art.js';
const app=document.querySelector('#app');
const modal=document.querySelector('#modal');
const titles=['بوابات إفريقيا','حكايات الانتشار','سجل الفتوحات','آثار تركت بصمتها'];
const desc=['تتبّع المعابر التي بدأت منها الرحلة.','اكتشف دور الناس في نشر الإسلام.','اربط الأماكن بالقادة والأحداث.','تعرّف على أثرٍ امتد عبر الأجيال.'];
const arts=['map','book','flag','award'];
const state={profile:null,courses:[],course:null,progress:[],view:'landing',station:1,step:0,question:0,opened:new Set(),selectedCard:0,feedback:null,teacherTab:'courses',editor:null,editorId:null,editorSource:'',preview:false,authMode:'login',authRole:'student',sound:false,reports:[],bank:[],bankSource:null,generationSource:null};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ar=n=>Number(n).toLocaleString('ar-EG');
const done=a=>a&&(a.correct||a.attempts>=2);
const stationDone=id=>{const qs=state.course?.document.stations.find(s=>s.id===id)?.questions||[];return qs.length>0&&qs.every(q=>done(state.progress.find(a=>a.question_id===q.id)));};
const allDone=()=>[1,2,3,4].every(stationDone);
const finalDone=()=>state.course?.document.final.every(q=>done(state.progress.find(a=>a.question_id===q.id)));
const score=()=>state.progress.reduce((n,a)=>n+a.score,0);
const toast=m=>{const t=document.querySelector('#toast');t.textContent=m;t.classList.add('show');clearTimeout(window.aeToast);window.aeToast=setTimeout(()=>t.classList.remove('show'),5000);};
function showModal(html){document.querySelector('#modal-content').innerHTML=html;modal.showModal();}
modal.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close();});
function help(){showModal(`<h2>دليل المستكشف</h2><p>استكشف أربع محطات بأي ترتيب. في كل محطة: اكتشف المحتوى، جرّب نشاطًا، ثم أجب عن خمسة أسئلة.</p><ol><li>المحطات: ٦٠ درجة، بحد أقصى ١٥ لكل محطة.</li><li>التحدي النهائي: ٨ أسئلة، مجموعها ٤٠ درجة. يفتح بعد إتمام أسئلة المحطات.</li><li>لكل سؤال محاولتان: الإجابة الصحيحة من الأولى تمنح الدرجة كاملة؛ ومن الثانية تمنح درجة واحدة بالمحطات ودرجتين بالنهائي.</li><li>بعد المحاولة الثانية يمكنك استكمال الرحلة حتى عند الخطأ. راجع التفسير لتتعلم.</li><li>الدرجات والإجابات تُحفظ في حسابك سحابيًا. لا يوجد مؤقت.</li><li>الأختام رمزية ولا تضيف درجات. الشهادة تظهر بعد إتمام ٢٨ سؤالًا.</li></ol><p>زر الصوت يفعّل القراءة باستخدام صوت المتصفح إن توفّر. كل المحتوى متاح كنص.</p>`);}
function header(){return `<header class="topbar">${brand()}<nav class="toplinks"><button data-action="help">كيف تعمل الرحلة؟</button><button data-action="auth-teacher">للمعلم</button><button class="btn small outline" data-action="auth">تسجيل الدخول ${icon('arrow')}</button></nav></header>`;}
function landing(){return `<div class="landing">${header()}<main id="main"><section class="hero"><div><div class="eyebrow">رحلة تعليمية · الصف الأول الإعدادي</div><h1>افتح الخريطة.<br>اكتشف الحكاية.<br><em>واترك بصمتك.</em></h1><p class="lead">انطلق في رحلة عبر إفريقيا، واكتشف كيف انتشر الإسلام، ومن حملوا رسالته، وما تركه من أثر في حياة الشعوب.</p><div class="hero-actions"><button class="btn" data-action="auth">ابدأ رحلتك ${icon('arrow')}</button><button class="btn outline" data-action="help">${icon('compass')} تعرّف على الرحلة</button></div><div class="hero-note"><span></span> تعلّم على مهلك · اكتشف بطريقتك · تقدّمك محفوظ</div></div><div class="hero-art">${atlas()}<div class="compass-rose">${icon('compass').replace('class="icon"','style="width:100%;height:auto" class="icon"')}</div><div class="float-label a"><span class="seal">✦</span><div>لكل محطة حكاية<small>أربع محطات… ورحلة واحدة</small></div></div><div class="float-label b">${icon('award')}<div>جوازك ينتظر أول ختم<small>اكتشف، جرّب، وأنجز</small></div></div><span class="art-caption">THE JOURNEY OF DISCOVERY</span></div></section><div class="stats-strip"><div><strong>٤</strong><small>محطات استكشاف</small></div><div><strong>٢٨</strong><small>سؤالًا وتحديًا</small></div><div><strong>١٠٠</strong><small>درجة للإنجاز</small></div><div><strong>∞</strong><small>فضول بلا حدود</small></div></div><section class="section"><div class="section-heading"><div><div class="eyebrow">على امتداد الخريطة</div><h2>أربع محطات. حكاية تستحق أن تُروى.</h2></div><p>من طرق الوصول… إلى الأثر الذي بقي.</p></div><div class="station-grid">${titles.map((t,i)=>`<article class="station-card"><span class="number">0${i+1}</span><div class="art-icon">${icon(arts[i])}</div><h3>${t}</h3><p>${desc[i]}</p><button class="text-btn full card-link" data-action="auth"><span>اكتشف المحطة</span>${icon('arrow')}</button></article>`).join('')}</div></section></main><footer class="footer"><span>مستكشف إفريقيا © ${new Date().getFullYear()} · رحلة انتشار الإسلام في إفريقيا</span><span>المعرفة تبدأ بسؤال.</span></footer></div>`;}
function auth(){const signup=state.authMode==='signup',reset=state.authMode==='reset',recovery=state.authMode==='recovery';return `${header()}<main id="main" class="auth-wrap"><section class="auth-story"><div class="eyebrow">كل رحلة تبدأ بخطوة</div><h1>مكانك على الخريطة<br>مستنيك.</h1><p>حساب واحد يحتفظ برحلتك، أختامك، وكل ما اكتشفته.<br>ادخل من أي جهاز، وكمل من آخر محطة.</p>${atlas()}</section><section class="auth-card"><span class="badge">${icon(state.authRole==='teacher'?'book':'compass')} ${state.authRole==='teacher'?'مساحة المعلم':'مساحة المستكشف'}</span><h2 style="margin-top:15px">${recovery?'كلمة مرور جديدة':reset?'استعادة كلمة المرور':signup?'رحلتك تبدأ هنا':'أهلًا برجوعك'}</h2><p class="sub">${reset?'هنرسل رابط الاستعادة إلى بريدك.':recovery?'اختر كلمة مرور جديدة لحسابك.':signup?'أنشئ حسابك واحفظ إنجازاتك سحابيًا.':'سجّل دخولك وكمل حكايتك.'}</p>${!reset&&!recovery?`<div class="tabs"><button data-action="auth-mode" data-mode="login" class="${!signup?'active':''}">تسجيل الدخول</button><button data-action="auth-mode" data-mode="signup" class="${signup?'active':''}">حساب جديد</button></div><div class="tabs"><button data-action="auth-role" data-role="student" class="${state.authRole==='student'?'active':''}">أنا طالب</button><button data-action="auth-role" data-role="teacher" class="${state.authRole==='teacher'?'active':''}">أنا معلم</button></div>`:''}<form id="auth-form">${signup?'<label class="field">اسمك<input name="name" required minlength="2" maxlength="100" autocomplete="name" placeholder="الاسم الذي سيظهر في شهادة إنجازك"></label>':''}${!recovery?'<label class="field">البريد الإلكتروني<input name="email" type="email" required autocomplete="email" dir="ltr" placeholder="name@example.com"></label>':''}${!reset?'<label class="field">كلمة المرور<input name="password" type="password" required minlength="8" autocomplete="'+(signup||recovery?'new-password':'current-password')+'" dir="ltr" placeholder="٨ أحرف على الأقل"></label>':''}${state.authRole==='teacher'&&signup?'<label class="field">رمز دعوة المعلم<input name="invite" required autocomplete="off" dir="ltr" placeholder="الرمز الذي حصلت عليه من مسؤول الموقع"></label>':''}<div id="auth-notice" role="alert"></div><button class="btn full" type="submit">${reset?'إرسال رابط الاستعادة':recovery?'حفظ كلمة المرور':signup?'إنشاء الحساب':'دخول إلى '+(state.authRole==='teacher'?'لوحة المعلم':'رحلتي')} ${icon('arrow')}</button></form>${!reset&&!recovery?'<button class="text-btn full" data-action="auth-mode" data-mode="reset">نسيت كلمة المرور؟</button>':'<button class="text-btn full" data-action="auth-mode" data-mode="login">الرجوع لتسجيل الدخول</button>'}<p class="muted" style="text-align:center;margin:18px 0 0">${icon('shield')} بياناتك وتقدّمك مرتبطان بحسابك.</p></section></main>`;}
function shell(content){const teacher=state.profile.role==='teacher';const nav=teacher?[['teacher','book','لوحة المعلم'],['map','map','معاينة الرحلة'],['passport','award','جواز المستكشف'],['help','help','دليل الاستخدام']]:[['map','map','خريطة الرحلة'],['passport','award','جواز المستكشف'],['certificate','flag','شهادة الإنجاز'],['help','help','دليل الاستخدام']];return `<div class="app-layout"><aside class="sidebar">${brand()}<nav><span class="nav-label">${teacher?'مساحة التعليم':'مساحة الاستكشاف'}</span>${nav.map(([v,i,t])=>`<button class="nav-btn ${state.view===v?'active':''}" data-action="nav" data-view="${v}">${icon(i)}${t}</button>`).join('')}</nav><div class="passport-bottom muted">${icon('shield')} متصل بحسابك السحابي<br>رحلتك محفوظة أينما ذهبت.</div><div class="sidebar-bottom"><div class="profile-box"><span class="avatar">${esc(state.profile.display_name[0])}</span><div>${esc(state.profile.display_name)}<small>${teacher?'حساب معلم':'مستكشف · أولى إعدادي'}</small></div></div><button class="text-btn" data-action="logout">${icon('logout')} تسجيل الخروج</button></div></aside><div class="app-main"><header class="app-header"><span class="desktop-crumb">مساحة ${teacher?'المعلم':'المستكشف'} <span style="margin:0 8px">/</span> ${esc({map:'خريطة الرحلة',station:'داخل المحطة',final:'التحدي النهائي',teacher:'إدارة المحتوى',passport:'جواز المستكشف',certificate:'شهادة الإنجاز'}[state.view]||'الرحلة')}</span><span class="mobile-brand">${brand()}</span><div class="row"><span class="badge">${teacher?'معلم':'مستكشف'} · ${esc(state.profile.display_name.split(' ')[0])}</span><button class="icon-btn" data-action="sound" aria-label="${state.sound?'كتم القراءة الصوتية':'تفعيل القراءة الصوتية'}">${icon(state.sound?'sound':'mute')}</button><button class="icon-btn" data-action="help" aria-label="المساعدة">${icon('help')}</button><button class="icon-btn" data-action="logout" aria-label="تسجيل الخروج">${icon('logout')}</button></div></header><main id="main" class="workspace">${content}</main></div></div>`;}
function passportCard(){const completed=[1,2,3,4].filter(stationDone).length;return `<aside class="passport"><div><span class="mini">وثيقة رحلتك الشخصية</span><h3>جواز المستكشف ${icon('compass')}</h3><p class="mini">${esc(state.profile.display_name)}</p><div class="score">${ar(score())}<small> / ١٠٠ درجة</small></div></div><div><div class="progress-track"><span style="width:${Math.round(state.progress.filter(done).length/28*100)}%"></span></div><span class="mini">${ar(completed)} من ٤ محطات مكتملة</span><div class="stamps">${titles.map((t,i)=>`<span class="stamp ${stationDone(i+1)?'earned':''}" title="${t}: ${stationDone(i+1)?'مكتملة':'لم تكتمل'}" aria-label="${t}: ${stationDone(i+1)?'مكتملة':'لم تكتمل'}">${stationDone(i+1)?'✦':ar(i+1)}</span>`).join('')}</div></div><div class="passport-bottom">${allDone()?'أختامك الأربعة جاهزة. التحدي النهائي ينتظرك!':'كل اكتشاف خطوة، وكل محطة مكتملة ختم جديد في جوازك.'}</div></aside>`;}
function courseSelect(){return `<select id="course-select" class="course-select" aria-label="اختر نسخة الدرس">${state.courses.filter(c=>c.status==='published').map(c=>`<option value="${c.id}" ${state.course?.id===c.id?'selected':''}>${esc(c.title)} · ${new Date(c.created_at).toLocaleDateString('ar-EG')}</option>`).join('')}</select>`;}
function mapView(){if(!state.course)return '<div class="empty">لا توجد رحلة منشورة حاليًا. سيضيف المعلم المحتوى قريبًا.</div>';const d=state.course.document;return `<div class="welcome-row"><div><div class="eyebrow">خريطتك نحو المعرفة</div><h1>أهلًا ${esc(state.profile.display_name.split(' ')[0])}، إلى أين نذهب اليوم؟</h1><p>${esc(d.title)} · اختَر محطة، وافتح حكاية جديدة.</p></div>${courseSelect()}</div>${state.preview?'<div class="notice">وضع معاينة المعلم: كل المحطات والتحدي مفتوحة للتجربة. لا تُسجّل درجات طلاب.</div>':''}<div class="journey-layout"><section class="journey-map"><span class="map-tag">${icon('compass')} خريطة الرحلة · رسم توضيحي</span>${atlas()}${d.stations.map((s,i)=>`<button class="map-point ${stationDone(s.id)?'done':''}" style="left:${[61,65,39,34][i]}%;top:${[29,51,22,56][i]}%" data-action="station" data-id="${s.id}" aria-label="افتح ${esc(s.title)}">${stationDone(s.id)?'✓':ar(s.id)}<span>${esc(s.title)}</span></button>`).join('')}</section>${passportCard()}</div><section class="app-stations"><div class="section-heading"><div><h2 style="font-size:19px">محطات رحلتك</h2></div><p>اختَر ترتيبك. اكتشفها جميعًا.</p></div><div class="station-grid">${d.stations.map((s,i)=>`<article class="station-card"><span class="number">0${s.id}</span><div class="art-icon">${icon(arts[i])}</div><h3>${esc(s.title)}</h3><p>${desc[i]}</p><div class="card-link"><span>${stationDone(s.id)?'✦ تم الحصول على الختم':'٥ أسئلة · ١٥ درجة'}</span><button class="icon-btn" data-action="station" data-id="${s.id}" aria-label="افتح ${esc(s.title)}">${icon('arrow')}</button></div></article>`).join('')}</div></section><section class="final-banner"><div><h3>${icon(allDone()||state.preview?'flag':'lock')} التحدي النهائي</h3><p>${allDone()||state.preview?'أنت جاهز لتجمع خيوط الحكاية. ٨ أسئلة بانتظارك.':'اجمع أختام المحطات الأربع لفتح التحدي النهائي.'}</p></div><button class="btn ${allDone()||state.preview?'gold':'outline'}" data-action="final" ${!allDone()&&!state.preview?'disabled':''}>${finalDone()?'راجع التحدي':'ابدأ التحدي'} ${icon('arrow')}</button></section>`;}
function currentStation(){return state.course.document.stations.find(s=>s.id===state.station);}
function stationView(){const s=currentStation();const step=['ابدأ','اكتشف','جرّب','تحدَّ','أنجزت'];let content='';if(state.step===0)content=`<div class="intro-panel"><div><span class="badge gold">المحطة ${ar(s.id)} من ٤</span><h2>${esc(s.title)}</h2><p>${esc(s.intro)}</p><p class="muted">استكشف المعلومات أولًا، ثم جرّب نشاطًا للتدريب، وأجب عن خمسة أسئلة لتجمع ختم المحطة.</p><button class="btn" data-action="step" data-step="1">ابدأ الاستكشاف ${icon('arrow')}</button></div><div class="big-art">${icon(arts[s.id-1])}</div></div>`;
 if(state.step===1)content=discovery(s);
 if(state.step===2)content=practice(s);
 if(state.step===3)content=quiz(s.questions,s.id);
 if(state.step===4){const completed=stationDone(s.id);const points=state.progress.filter(a=>a.station===s.id).reduce((n,a)=>n+a.score,0);content=`<div class="completion"><div class="medal">${completed?'✦':'⌖'}</div><h2>${completed?'أضفت ختمًا جديدًا لجوازك!':'خطوتك التالية: أكمل التحدي'}</h2><p>${completed?'اكتملت محطة '+esc(s.title)+'. تقدر تراجع الشرح والتفسيرات في أي وقت.':'أكمل الأسئلة الخمسة للحصول على ختم هذه المحطة. لكل سؤال محاولتان.'}</p><div class="score">${ar(points)} <small>/ ١٥</small></div><div class="hero-actions" style="justify-content:center"><button class="btn" data-action="${completed?'nav':'step'}" ${completed?'data-view="map"':'data-step="3"'}>${completed?'العودة للخريطة':'أكمل الأسئلة'} ${icon('arrow')}</button><button class="btn outline" data-action="review">مراجعة ما تعلمت</button></div></div>`;}
 return `<div class="station-heading"><div><div class="eyebrow">${esc(state.course.document.title)}</div><h1>${esc(s.title)}</h1><p>${esc(s.intro)}</p></div><button class="btn outline small" data-action="nav" data-view="map">${icon('map')} الخريطة</button></div><nav class="stepper" aria-label="مراحل المحطة">${step.map((t,i)=>`<button class="${state.step===i?'active':''}" data-action="step" data-step="${i}" aria-current="${state.step===i?'step':'false'}">${ar(i+1)} · ${t}</button>`).join('')}</nav><section class="panel">${content}</section>`;
}
function discovery(s){const c=s.cards[state.selectedCard]||s.cards[0];if(s.id===1)return `<div class="interactive-map"><div class="map-region">${atlas()}${s.cards.slice(1,5).map((c,i)=>`<button class="route-hotspot ${state.selectedCard===i+1?'active':''}" style="left:${[59,65,75,55][i]}%;top:${[23,36,55,15][i]}%" data-action="card" data-card="${i+1}" aria-label="${esc(c.title)}">${ar(i+1)}</button>`).join('')}</div><div class="detail-box"><span class="badge">${icon('map')} اضغط على علامات الخريطة</span><h2 style="margin-top:18px">${esc(c.title)}</h2><p>${esc(c.text)}</p><button class="text-btn" data-action="read" data-text="${esc(c.text)}">${icon('sound')} استمع للشرح</button><div class="inline-actions">${s.cards.map((c,i)=>`<button class="btn small ${state.selectedCard===i?'':'outline'}" data-action="card" data-card="${i}">${esc(c.title)}</button>`).join('')}</div></div></div><p class="muted" style="margin-top:15px">المواضع والمسارات تخطيطية لتوضيح الفكرة، وليست خريطة ملاحة أو حدودًا تاريخية دقيقة.</p><button class="btn" data-action="step" data-step="2">جرّب اكتشافك ${icon('arrow')}</button>`;
 if(s.id===3)return `<h2 class="text-green" style="font-size:20px">تتبّع امتداد الفتوحات نحو الغرب</h2><p class="muted">اضغط على مراحل السجل لعرض الحدث. الترتيب مكاني وتاريخي عام؛ لا يمثل مددًا زمنية متساوية.</p><div class="timeline">${s.cards.map((c,i)=>`<button class="${state.selectedCard===i?'active':''}" data-action="card" data-card="${i}"><span class="dot">${ar(i+1)}</span>${esc(c.title.split('—')[0])}</button>`).join('')}</div><article class="discover-card open"><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p><button class="text-btn" data-action="read" data-text="${esc(c.text)}">${icon('sound')} استمع للحدث</button></article><div class="practice-actions"><button class="btn" data-action="step" data-step="2">جرّب ترتيب الأحداث ${icon('arrow')}</button></div>`;
 return `<div class="section-heading"><div><span class="eyebrow">${s.id===2?'افتح الحكاية، واكتشف الأسلوب':'معرض الأثر الحضاري'}</span><h2 style="font-size:22px">${s.id===2?'وراء كل طريقة… ناس وحكايات':'حكاية استمر أثرها'}</h2></div><span class="badge">${ar(state.opened.size)} / ${ar(s.cards.length)} بطاقات مستكشفة</span></div><div class="discovery-grid">${s.cards.map((c,i)=>`<button class="discover-card ${state.opened.has(i)?'open':''}" data-action="open-card" data-card="${i}" aria-expanded="${state.opened.has(i)}"><h3>${esc(c.title)} ${icon(state.opened.has(i)?'check':s.id===2?'book':'award')}</h3>${state.opened.has(i)?`<p>${esc(c.text)}</p>`:'<small>اضغط لاكتشاف الحكاية ←</small>'}</button>`).join('')}</div><div class="practice-actions"><button class="btn" data-action="step" data-step="2">انتقل إلى التدريب ${icon('arrow')}</button></div>`;}
function practice(s){const cards=s.cards.slice(0,5);const shuffled=[...cards].reverse();
 if(s.id===3){if(!state.practiceOrder||state.practiceOrder.length!==cards.length)state.practiceOrder=cards.map((c,i)=>i).reverse();return `<div class="eyebrow">مساحة للتجربة · ترتيب الأحداث</div><h2 class="text-green" style="font-size:22px;margin-top:12px">أعِد بناء سجل الفتوحات</h2><p class="muted">رتّب المراحل من بداية الطريق إلى استكماله غربًا. استخدم زري السابق والتالي لتحريك كل حدث.</p><form id="practice-form" data-order="1">${state.practiceOrder.map((index,i)=>`<div class="practice-row"><span><strong>${ar(i+1)}.</strong> ${esc(cards[index].title)}</span><div class="inline-actions"><button type="button" class="btn outline small" data-action="move-event" data-index="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="قدّم ${esc(cards[index].title)}">↑ السابق</button><button type="button" class="btn outline small" data-action="move-event" data-index="${i}" data-direction="1" ${i===cards.length-1?'disabled':''} aria-label="أخّر ${esc(cards[index].title)}">↓ التالي</button></div></div>`).join('')}<div id="practice-feedback" role="status"></div><div class="practice-actions"><button class="btn" type="submit">تحقّق من الترتيب ${icon('check')}</button><button class="btn outline" type="button" data-action="step" data-step="3">انتقل للتحدي ${icon('arrow')}</button></div></form>`;}
 return `${s.id===1&&s.cards.length>=5?mapPractice(s):''}<div class="eyebrow">مساحة للتجربة · بدون درجات</div><h2 class="text-green" style="font-size:22px;margin-top:12px">${s.id===4?'صنّف الأثر الحضاري':s.id===2?'حلّل الحكاية وحدّد أسلوب الانتشار':'اربط الطريق بدوره'}</h2><p class="muted">اقرأ الوصف، ثم اختر البطاقة التي يعبّر عنها. ارجع للشرح في أي وقت.</p><form id="practice-form">${cards.map((c,i)=>`<div class="practice-row"><span>${esc(c.text.split(/[.؟]/)[0])}.</span><select name="p${i}" required aria-label="اختر عنوان الفكرة ${i+1}"><option value="">اختر العنوان…</option>${shuffled.map(x=>`<option value="${esc(x.title)}">${esc(x.title)}</option>`).join('')}</select></div>`).join('')}<div id="practice-feedback" role="status"></div><div class="practice-actions"><button class="btn" type="submit">تحقّق من الربط ${icon('check')}</button><button class="btn outline" type="button" data-action="step" data-step="3">انتقل للتحدي ${icon('arrow')}</button></div></form>`;}
function mapPractice(s){const index=state.practiceMapIndex||0;return `<div class="eyebrow">تحدّي المكان · تدريب بدون درجات</div><h2 class="text-green" style="font-size:21px;margin-top:12px">أين ${esc(s.cards[index+1].title)}؟</h2><p class="muted">اضغط على علامته في الرسم، ثم اربط الطرق بأدوارها في النشاط التالي.</p><div class="map-region" style="position:relative;max-width:480px;margin:auto">${atlas()}${s.cards.slice(1,5).map((c,i)=>`<button type="button" class="route-hotspot" style="left:${[59,65,75,55][i]}%;top:${[23,36,55,15][i]}%" data-action="practice-map" data-choice="${i}" aria-label="الموقع رقم ${i+1}">${ar(i+1)}</button>`).join('')}</div><div id="map-practice-feedback" role="status"></div><div class="practice-actions" style="margin-bottom:30px"><button class="btn outline small" data-action="practice-map-next">${index===3?'تدريب من البداية':'المعبر التالي'} ${icon('arrow')}</button></div>`;}
function quiz(qs,station){const q=qs[state.question]||qs[0];const a=state.progress.find(x=>x.question_id===q.id);const finished=done(a);const feedback=state.feedback;return `<div class="quiz-layout"><aside class="question-nav"><h3>خريطة الأسئلة</h3><div class="question-dots">${qs.map((q,i)=>`<button data-action="question" data-question="${i}" class="${state.question===i?'active':''} ${done(state.progress.find(a=>a.question_id===q.id))?'done':''}" aria-label="السؤال ${i+1}">${ar(i+1)}</button>`).join('')}</div><p>الإجابة الأولى: ${station===5?'٥':'٣'} درجات<br>الإجابة الثانية: ${station===5?'درجتان':'درجة واحدة'}<br>محاولتان لكل سؤال.</p></aside><div class="question-box"><span class="badge gold">${station===5?'التحدي النهائي':'تحدّي المحطة'} · سؤال ${ar(state.question+1)} من ${ar(qs.length)}</span><h2>${esc(q.prompt)}</h2><form id="quiz-form" data-id="${q.id}"><div class="options">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="choice" value="${i}" required ${finished?'disabled':''} ${a?.last_choice===i?'checked':''}><span class="option-letter">${['أ','ب','ج','د'][i]}</span><span>${esc(o)}</span></label>`).join('')}</div>${feedback?`<div class="feedback ${feedback.correct?'':'wrong'}" role="status"><strong>${feedback.correct?'إجابة موفّقة!':feedback.finished?'انتهت المحاولتان؛ نكمل ونتعلم.':'اقتربت… جرّب مرة ثانية.'}</strong><br>${esc(feedback.explanation)}${feedback.answer!==null&&feedback.answer!==undefined?'<br>الإجابة الصحيحة: '+esc(q.options[feedback.answer]):''}<br>درجتك في السؤال: ${ar(feedback.score)}</div>`:finished?`<div class="notice">تم حفظ هذا السؤال سحابيًا · ${ar(a.score)} درجات. تقدر تراجع التفسير من زر المراجعة.</div>`:''}<div id="quiz-error" role="alert"></div><div class="quiz-bottom">${!finished?'<button class="btn" type="submit">تأكيد الإجابة '+icon('check')+'</button>':'<button class="btn outline" type="button" data-action="review">راجع التفسير</button>'}<button class="btn ${finished?'':'outline'}" type="button" data-action="next-question">${state.question===qs.length-1?'عرض الإنجاز':'السؤال التالي'} ${icon('arrow')}</button></div></form></div></div>`;}
function finalView(){if(!allDone()&&!state.preview)return '<div class="notice">أكمل المحطات الأربع لفتح هذا التحدي.</div>';return `<div class="station-heading"><div><div class="eyebrow">آخر خطوة في الرحلة</div><h1>التحدي النهائي</h1><p>اجمع ما اكتشفته في المحطات الأربع. ٨ أسئلة · ٤٠ درجة · بدون مؤقت.</p></div><button class="btn outline small" data-action="nav" data-view="map">${icon('map')} الخريطة</button></div><section class="panel">${quiz(state.course.document.final,5)}</section>`;}
function passportView(){if(!state.course)return '<div class="empty">اختر رحلة منشورة أولًا.</div>';return `<div class="welcome-row"><div><div class="eyebrow">كل ختم حكاية تعلّمتها</div><h1>جواز المستكشف</h1><p>إنجازاتك محفوظة سحابيًا لهذه النسخة من الدرس.</p></div>${courseSelect()}</div><div class="journey-layout"><div class="panel"><h2 class="text-green" style="font-size:21px">أختام رحلتك</h2>${state.course.document.stations.map(s=>`<div class="course-row"><div><h3>${stationDone(s.id)?'✦':'◌'} ${esc(s.title)}</h3><p>${stationDone(s.id)?'مكتملة':'قيد الاستكشاف'} · ${ar(state.progress.filter(a=>a.station===s.id).reduce((n,a)=>n+a.score,0))} / ١٥ درجة</p></div><button class="btn outline small" data-action="station" data-id="${s.id}">افتح المحطة ${icon('arrow')}</button></div>`).join('')}<div class="practice-actions"><button class="btn" data-action="review">مراجعة الإجابات</button><button class="btn outline" data-action="nav" data-view="certificate">شهادة الإنجاز</button></div></div>${passportCard()}</div>`;}
function certificateView(){if(!state.course||!allDone()||!finalDone())return `<section class="panel completion"><div class="medal">${icon('lock')}</div><h2>شهادتك تنتظر آخر اكتشاف</h2><p>أكمل أسئلة المحطات الأربع والتحدي النهائي لعرض شهادتك. الدرجة لا تمنعك من إتمام الرحلة.</p><button class="btn" data-action="nav" data-view="map">العودة للخريطة ${icon('arrow')}</button></section>`;return `<section class="certificate">${brand()}<div class="seal">✦</div><div class="eyebrow" style="justify-content:center">وثيقة إتمام رحلة تعليمية</div><h1>شهادة المستكشف</h1><p>تُمنح هذه الشهادة إلى</p><h2>${esc(state.profile.display_name)}</h2><p>لإتمام رحلة «${esc(state.course.document.title)}»<br>واستكشاف المحطات الأربع واجتياز جميع أنشطة التحدي.</p><h2>${ar(score())} <small>من ١٠٠ درجة</small></h2><p>أربعة أختام · حكاية اكتملت · معرفة تستمر</p><div class="muted">معرّف الرحلة: ${esc(state.course.id.slice(0,8))} · معرّف المستكشف: ${esc(state.profile.id.slice(0,8))}<br>شهادة إتمام تعليمية مولّدة من نتائج الحساب السحابي.</div></section><div class="inline-actions no-print"><button class="btn" data-action="print">${icon('download')} طباعة / حفظ PDF</button><button class="btn outline" data-action="review">مراجعة الإجابات</button><button class="btn outline" data-action="nav" data-view="map">خريطة الرحلة</button></div>`;}
function teacherView(){let body='';if(state.teacherTab==='courses')body=`<section class="panel"><div class="section-heading"><div><h2 style="font-size:22px">مكتبة المحتوى السحابي</h2><p>النسخ المنشورة ثابتة؛ انسخ أي نسخة لمسودة جديدة لتطويرها.</p></div><button class="btn small" data-action="teacher-tab" data-tab="generate">${icon('spark')} ولّد رحلة جديدة</button></div>${state.courses.map(c=>`<article class="course-row"><div><h3>${esc(c.title)} <span class="badge ${c.status==='published'?'':'gold'}">${c.status==='published'?'منشور':'مسودة'}</span></h3><p>${new Date(c.created_at).toLocaleDateString('ar-EG')} · ${c.owner_id?'نسخة معلم':'النسخة الأساسية'} · ${c.id.slice(0,8)}</p></div><div class="inline-actions"><button class="btn outline small" data-action="edit-course" data-id="${c.id}">${icon('pen')} ${c.status==='draft'?'تحرير':'نسخ وتحرير'}</button>${c.status==='published'?`<button class="btn light small" data-action="preview-course" data-id="${c.id}">معاينة</button>`:''}</div></article>`).join('')}</section><section class="panel"><h3 class="text-green">دعوة معلم آخر</h3><p class="muted">أنشئ رمزًا خاصًا لمرة واحدة، صالحًا لسبعة أيام. لا تشاركه مع الطلاب.</p><button class="btn outline small" data-action="invite">إنشاء رمز دعوة</button><div id="invite-result" role="status"></div></section>`;
 if(state.teacherTab==='generate')body=generatorView();
 if(state.teacherTab==='bank')body=bankView();
 if(state.teacherTab==='editor')body=editorView();
 if(state.teacherTab==='reports')body=reportsView();
 return `<div class="welcome-row"><div><div class="eyebrow">مساحة تصنع فيها رحلات التعلم</div><h1>لوحة المعلم</h1><p>أهلاً ${esc(state.profile.display_name)}. المحتوى، التوليد، ومتابعة المستكشفين في مكان واحد.</p></div><button class="btn outline small" data-action="refresh">${icon('clock')} تحديث البيانات</button></div><nav class="teacher-tabs">${[['courses','مكتبة المحتوى'],['generate','توليد المحتوى'],['bank','بنك الأسئلة'],['editor','المحرر والمراجعة'],['reports','تقدّم الطلاب']].map(([t,l])=>`<button class="${state.teacherTab===t?'active':''}" data-action="teacher-tab" data-tab="${t}">${l}</button>`).join('')}</nav>${body}`;
}
function generatorView(){const sources=state.courses.filter(c=>c.status==='published');return `<div class="teacher-grid"><section class="panel"><span class="badge gold">${icon('spark')} مولّد من البنك السحابي</span><h2 class="text-green" style="margin-top:15px;font-size:24px">محتوى معتمد. رحلة جديدة كل مرة.</h2><p class="muted">يختار الباك إند أسئلة متنوعة من البنك، ويغيّر ترتيبها واختياراتها، ويجمعها مع شرح الدرس في مسودة جديدة. لا يستخدم خدمة ذكاء اصطناعي خارجية.</p><form id="generate-form"><label class="field">الدرس المصدر<select name="source_id" required>${sources.map(c=>`<option value="${c.id}" ${state.generationSource===c.id?'selected':''}>${esc(c.title)} · ${c.id.slice(0,8)}</option>`).join('')}</select></label><label class="field">عنوان النسخة الجديدة<input name="title" required minlength="3" maxlength="160" value="${esc((state.course?.document.title||'انتشار الإسلام في إفريقيا')+' — نسخة تدريبية')}" placeholder="مثال: رحلة المراجعة الأولى"></label><label class="field">تركيز أسئلة التحدي النهائي<select name="focus"><option value="0">تنويع متوازن من البنك</option>${titles.map((t,i)=>`<option value="${i+1}">تركيز على ${t}</option>`).join('')}</select></label><div id="generate-notice" role="status"></div><button class="btn full" type="submit">${icon('spark')} توليد نسخة من المحتوى المخزّن</button></form></section><aside><section class="panel"><h3 class="text-green">كيف تتكوّن النسخة؟</h3><p class="muted">٤ محطات بشرحها المعتمد.<br>٥ أسئلة متنوعة لكل محطة.<br>٨ أسئلة نهائية لا تتكرر مع أسئلة المحطات.<br>خلط الاختيارات مع الحفاظ على صحة مفتاح الإجابة.<br>حفظ سحابي كمسودة للمراجعة والنشر.</p><div class="notice">المحتوى يأتي من بيانات الباك إند فقط. إضافة موضوع أو معلومة جديدة تتم من المحرر والبنك، وليس بتأليف آلي من خارج المرجع.</div></section><section class="panel"><h3 class="text-green">كبّر بنك المعرفة</h3><p class="muted">البنك الأساسي يضم ٥٦ سؤالًا معتمدًا. أضف أسئلة وحرّرها أو أوقفها مؤقتًا من تبويب بنك الأسئلة.</p><button class="btn outline small" data-action="teacher-tab" data-tab="bank">${icon('book')} افتح بنك الأسئلة</button></section></aside></div>`;}
async function loadBank(){state.bankSource=state.bankSource||state.generationSource||state.courses.find(c=>!c.owner_id&&c.status==='published')?.id||state.courses.find(c=>c.status==='published')?.id;if(state.bankSource)state.bank=await cloud.rpc('ae_bank_list',{p_source:state.bankSource});}
function bankView(){return `<section class="panel"><div class="section-heading"><div><h2 style="font-size:22px">بنك المعرفة والأسئلة</h2><p>التوليد يستخدم الأسئلة النشطة من هذا البنك. تعديل البنك لا يغيّر النسخ المنشورة أو نتائج الطلاب.</p></div><button class="btn small" data-action="bank-new">${icon('pen')} أضف سؤالًا</button></div><label class="field">الدرس المرتبط بالبنك<select id="bank-course-select">${state.courses.filter(c=>c.status==='published').map(c=>`<option value="${c.id}" ${state.bankSource===c.id?'selected':''}>${esc(c.title)} · ${c.id.slice(0,8)}</option>`).join('')}</select></label><div class="info-grid">${[1,2,3,4,5].map(i=>`<div class="info-tile"><strong>${ar(state.bank.filter(b=>b.station===i&&b.active).length)}</strong><small>${i===5?'أسئلة النهائي':titles[i-1]}</small></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>المحطة</th><th>السؤال</th><th>الحالة</th><th>التحرير</th></tr></thead><tbody>${state.bank.map(b=>`<tr><td>${b.station===5?'النهائي':esc(titles[b.station-1])}</td><td style="white-space:normal;min-width:240px">${esc(b.question.prompt)}</td><td><span class="badge ${b.active?'':'gold'}">${b.active?'نشط':'موقوف'}</span></td><td><div class="inline-actions"><button class="btn outline small" data-action="bank-edit" data-id="${b.id}">تحرير</button><button class="text-btn" data-action="bank-toggle" data-id="${b.id}">${b.active?'إيقاف مؤقت':'تفعيل'}</button></div></td></tr>`).join('')}</tbody></table></div>${state.bank.length?'':'<div class="notice">هذا المصدر يستخدم أسئلته الأصلية. أول عملية توليد تجهّز له بنكًا سحابيًا، أو يمكنك إضافة أسئلة الآن.</div>'}</section>`;}
function editorView(){const d=state.editor;if(!d)return '<section class="panel empty">اختر نسخة من مكتبة المحتوى لتحريرها، أو ولّد مسودة جديدة.</section>';return `<section class="panel"><div class="section-heading"><div><h2 style="font-size:22px">مراجعة الرحلة وتحريرها</h2><p>راجع الشرح وصحة كل إجابة. التعديلات لا تُحفظ إلا بضغط «حفظ المسودة».</p></div><span class="badge gold">${state.editorId?'مسودة محفوظة':'نسخة جديدة غير محفوظة'}</span></div><form id="editor-form"><label class="field">عنوان الدرس<input name="title" value="${esc(d.title)}" required minlength="3" maxlength="160"></label><label class="field">وصف الرحلة<input name="subtitle" value="${esc(d.subtitle)}" maxlength="300"></label>${d.stations.map((s,si)=>`<details class="editor-section" ${si===0?'open':''}><summary>المحطة ${ar(s.id)} · ${esc(s.title)}</summary><label class="field">عنوان المحطة<input data-path="stations.${si}.title" value="${esc(s.title)}" required></label><label class="field">المقدمة<textarea data-path="stations.${si}.intro">${esc(s.intro)}</textarea></label><h4>بطاقات الشرح</h4>${s.cards.map((c,ci)=>`<details class="editor-section"><summary>${esc(c.title)}</summary><label class="field">عنوان البطاقة<input data-path="stations.${si}.cards.${ci}.title" value="${esc(c.title)}" required></label><label class="field">الشرح<textarea data-path="stations.${si}.cards.${ci}.text" required>${esc(c.text)}</textarea></label></details>`).join('')}<h4>أسئلة المحطة</h4>${s.questions.map((q,qi)=>questionEditor(q,`stations.${si}.questions.${qi}`,qi)).join('')}</details>`).join('')}<details class="editor-section"><summary>التحدي النهائي · ٨ أسئلة</summary>${d.final.map((q,i)=>questionEditor(q,`final.${i}`,i)).join('')}</details><details class="editor-section"><summary>النص المرجعي</summary><textarea name="source" maxlength="24000" class="source-area">${esc(state.editorSource)}</textarea></details><div id="editor-notice" role="status"></div><div class="editor-toolbar"><button class="btn" type="submit">${icon('check')} حفظ المسودة سحابيًا</button><button class="btn outline" type="button" data-action="preview-draft">معاينة التعديلات</button><button class="btn gold" type="button" data-action="publish">نشر النسخة بعد المراجعة</button><button class="text-btn" type="button" data-action="export-content">${icon('download')} تصدير JSON</button></div></form></section>`;}
function questionEditor(q,path,i){return `<details class="editor-section"><summary>${ar(i+1)} · ${esc(q.prompt)}</summary><label class="field">السؤال<textarea data-path="${path}.prompt" required>${esc(q.prompt)}</textarea></label><div class="form-grid">${q.options.map((o,j)=>`<label class="field">الاختيار ${['أ','ب','ج','د'][j]}<input data-path="${path}.options.${j}" value="${esc(o)}" required></label>`).join('')}</div><label class="field">الإجابة الصحيحة<select data-path="${path}.answer" data-number="1">${q.options.map((o,j)=>`<option value="${j}" ${q.answer===j?'selected':''}>${['أ','ب','ج','د'][j]}</option>`).join('')}</select></label><label class="field">التفسير والتغذية الراجعة<textarea data-path="${path}.explanation" required>${esc(q.explanation)}</textarea></label></details>`;}
function reportsView(){const r=state.reports;return `<div class="info-grid"><div class="info-tile"><strong>${ar(new Set(r.map(x=>x.id)).size)}</strong><small>طالب بدأ رحلة</small></div><div class="info-tile"><strong>${ar(r.filter(x=>x.finished===28).length)}</strong><small>رحلة مكتملة</small></div><div class="info-tile"><strong>${ar(r.length?Math.round(r.reduce((n,x)=>n+Number(x.score),0)/r.length):0)}</strong><small>متوسط الدرجات / ١٠٠</small></div></div><section class="panel"><div class="section-heading"><div><h2 style="font-size:22px">متابعة المستكشفين</h2><p>نتائج المحتوى الأساسي ونسخك المنشورة. صف مستقل لكل طالب ونسخة.</p></div><button class="btn outline small" data-action="export-reports">${icon('download')} تصدير CSV</button></div><label class="field">ابحث عن طالب أو درس<input id="report-search" placeholder="اكتب الاسم أو عنوان الدرس…"></label><div class="table-wrap"><table><thead><tr><th>المستكشف</th><th>نسخة الدرس</th><th>الدرجة</th><th>الأسئلة المكتملة</th><th>آخر نشاط</th></tr></thead><tbody>${r.map(x=>`<tr data-report-row><td>${esc(x.display_name)}</td><td>${esc(x.title)} · ${x.course_id.slice(0,8)}</td><td>${ar(x.score)} / ١٠٠</td><td>${ar(x.finished)} / ٢٨</td><td>${new Date(x.last_active).toLocaleString('ar-EG')}</td></tr>`).join('')}</tbody></table></div>${!r.length?'<div class="empty">لم يبدأ طلاب هذه الرحلة بعد. ستظهر النتائج هنا بعد أول إجابة محفوظة.</div>':''}</section>`;}
function render(){const content=state.view==='landing'?landing():state.view==='auth'?auth():shell(({map:mapView,station:stationView,final:finalView,passport:passportView,certificate:certificateView,teacher:teacherView}[state.view]||mapView)());app.innerHTML=content;bindForms();}
async function loadCourse(id){state.course=await cloud.rpc('ae_get_course',{p_id:id});state.progress=state.preview?[]:await cloud.rpc('ae_progress',{p_id:id});}
async function boot(){state.profile=await cloud.rpc('ae_me');state.preview=state.profile.role==='teacher';state.courses=await cloud.rpc('ae_list_courses');let previous;try{previous=localStorage.getItem('ae-course');}catch{}const c=state.courses.find(c=>c.id===previous&&c.status==='published')||state.courses.find(c=>c.status==='published');if(c)await loadCourse(c.id);state.view=state.preview?'teacher':'map';}
function go(view){if(view==='help'){help();return;}state.view=view;state.feedback=null;render();scrollTo({top:0,behavior:'instant'});}
function read(text){if(!('speechSynthesis'in window)){toast('القراءة الصوتية غير متاحة في هذا المتصفح. النص كامل أمامك.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ar';u.rate=.9;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('ar'));if(voice)u.voice=voice;speechSynthesis.speak(u);}
function tone(ok=true){if(!state.sound)return;try{const ctx=new AudioContext(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=ok?660:270;g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.18);o.start();o.stop(ctx.currentTime+.2);o.onended=()=>ctx.close();}catch{}}
function collectEditor(){const f=document.querySelector('#editor-form');if(!f)return state.editor;const d=structuredClone(state.editor);d.title=f.elements.title.value;d.subtitle=f.elements.subtitle.value;for(const input of f.querySelectorAll('[data-path]')){const path=input.dataset.path.split('.');let obj=d;for(const k of path.slice(0,-1))obj=obj[k];obj[path.at(-1)]=input.dataset.number?Number(input.value):input.value;}state.editor=d;state.editorSource=f.elements.source.value;return d;}
async function saveEditor(){const d=collectEditor();const result=await cloud.rpc('ae_save_draft',{p_id:state.editorId,p_document:d,p_source:state.editorSource});state.editorId=result.id;state.courses=await cloud.rpc('ae_list_courses');return result;}
async function review(){if(state.preview){const d=state.course.document;const qs=state.view==='station'?currentStation().questions:[...d.stations.flatMap(s=>s.questions),...d.final];showModal(`<h2>مراجعة المعلم</h2>${qs.map(q=>`<article class="review-item"><h3>${esc(q.prompt)}</h3><p>الإجابة: ${esc(q.options[q.answer])}</p><p>${esc(q.explanation)}</p></article>`).join('')}`);return;}const rows=await cloud.rpc('ae_review',{p_id:state.course.id});const filtered=state.view==='station'?rows.filter(r=>currentStation().questions.some(q=>q.id===r.id)):rows;showModal(`<h2>مراجعة اكتشافاتك</h2>${filtered.length?filtered.map(r=>`<article class="review-item"><h3>${r.correct?'✓':'◌'} ${esc(r.prompt)}</h3><p><strong>الإجابة الصحيحة:</strong> ${esc(r.answer)}</p><p>${esc(r.explanation)}</p><small>${ar(r.score)} درجات محفوظة</small></article>`).join(''):'<p>أكمل محاولات السؤال لعرض إجابته وتفسيره هنا.</p>'}`);}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action;try{
 if(a==='brand'){go(state.profile?'map':'landing');return;}
 if(a==='help'){help();return;}
 if(a==='auth'||a==='auth-teacher'){state.authRole=a==='auth-teacher'?'teacher':'student';state.authMode='login';go('auth');return;}
 if(a==='auth-mode'){state.authMode=b.dataset.mode;render();return;}
 if(a==='auth-role'){state.authRole=b.dataset.role;render();return;}
 if(a==='logout'){await cloud.logout();Object.assign(state,{profile:null,course:null,progress:[],view:'landing',editor:null});if('speechSynthesis'in window)speechSynthesis.cancel();render();return;}
 if(a==='nav'){go(b.dataset.view);return;}
 if(a==='sound'){state.sound=!state.sound;if(!state.sound&&'speechSynthesis'in window)speechSynthesis.cancel();render();toast(state.sound?'القراءة متاحة من زر استمع؛ المؤثرات مفعّلة.':'تم كتم الصوت.');return;}
 if(a==='station'){state.station=Number(b.dataset.id);state.step=0;state.question=0;state.opened=new Set();state.selectedCard=0;go('station');return;}
 if(a==='step'){state.step=Number(b.dataset.step);state.feedback=null;state.question=0;render();return;}
 if(a==='move-event'){const index=Number(b.dataset.index),next=index+Number(b.dataset.direction);if(next>=0&&next<state.practiceOrder.length){[state.practiceOrder[index],state.practiceOrder[next]]=[state.practiceOrder[next],state.practiceOrder[index]];render();}return;}
 if(a==='practice-map'){const correct=Number(b.dataset.choice)===(state.practiceMapIndex||0);document.querySelector('#map-practice-feedback').innerHTML='<div class="feedback '+(correct?'':'wrong')+'">'+(correct?'مكان صحيح! '+esc(currentStation().cards[(state.practiceMapIndex||0)+1].text):'راجع موضع المعبر على خريطة الاستكشاف ثم جرّب مرة أخرى.')+'</div>';tone(correct);return;}
 if(a==='practice-map-next'){state.practiceMapIndex=((state.practiceMapIndex||0)+1)%4;render();return;}
 if(a==='card'){state.selectedCard=Number(b.dataset.card);render();if(state.sound)read(currentStation().cards[state.selectedCard].text);return;}
 if(a==='open-card'){const i=Number(b.dataset.card);state.opened.add(i);render();if(state.sound)read(currentStation().cards[i].text);return;}
 if(a==='read'){state.sound=true;read(b.dataset.text);return;}
 if(a==='final'){if(!allDone()&&!state.preview)throw Error('أكمل المحطات الأربع أولًا.');state.question=0;go('final');return;}
 if(a==='question'){state.question=Number(b.dataset.question);state.feedback=null;render();return;}
 if(a==='next-question'){const qs=state.view==='final'?state.course.document.final:currentStation().questions;if(state.question<qs.length-1){state.question++;state.feedback=null;render();}else if(state.view==='final'){go('certificate');}else{state.step=4;state.feedback=null;render();}return;}
 if(a==='review'){b.disabled=true;await review();b.disabled=false;return;}
 if(a==='print'){window.print();return;}
 if(a==='teacher-tab'){if(state.teacherTab==='editor')collectEditor();state.teacherTab=b.dataset.tab;if(state.teacherTab==='reports')state.reports=await cloud.rpc('ae_reports');if(state.teacherTab==='bank')await loadBank();go('teacher');return;}
 if(a==='edit-course'){const c=await cloud.rpc('ae_get_course',{p_id:b.dataset.id});state.editor=structuredClone(c.document);state.editorSource=c.source||'';state.editorId=c.status==='draft'?c.id:null;state.teacherTab='editor';go('teacher');return;}
 if(a==='preview-course'){await loadCourse(b.dataset.id);go('map');return;}
 if(a==='preview-draft'){collectEditor();state.course={id:state.editorId,document:structuredClone(state.editor),status:'draft'};state.progress=[];go('map');return;}
 if(a==='publish'){collectEditor();showModal(`<h2>نشر نسخة جديدة للطلاب</h2><p>سيصبح درس «${esc(state.editor.title)}» متاحًا للطلاب. ستبقى هذه النسخة ثابتة بعد النشر للحفاظ على درجاتهم.</p><p>تأكد من مراجعة الحقائق والشرح والإجابات والتفسيرات. يمكنك إنشاء نسخة جديدة لأي تعديل لاحق.</p><label class="field"><input type="checkbox" id="publish-check">راجعت المحتوى والإجابات وأوافق على نشر النسخة.</label><button class="btn gold" id="confirm-publish" disabled>نشر النسخة</button><div id="publish-notice" role="status"></div>`);document.querySelector('#publish-check').onchange=e=>document.querySelector('#confirm-publish').disabled=!e.target.checked;document.querySelector('#confirm-publish').onclick=async e=>{e.target.disabled=true;try{await saveEditor();await cloud.rpc('ae_publish',{p_id:state.editorId});state.editorId=null;state.courses=await cloud.rpc('ae_list_courses');state.teacherTab='courses';modal.close();render();toast('تم نشر النسخة. أصبحت متاحة للطلاب.');}catch(err){document.querySelector('#publish-notice').textContent=err.message;e.target.disabled=false;}};return;}
 if(a==='refresh'){state.courses=await cloud.rpc('ae_list_courses');state.reports=await cloud.rpc('ae_reports');render();toast('تم تحديث البيانات من السحابة.');return;}
 if(a==='load-source'){const c=state.courses.find(x=>!x.owner_id&&x.status==='published')||state.courses.find(x=>x.status==='published');if(!c)throw Error('لا يوجد نص أساسي.');const d=await cloud.rpc('ae_get_course',{p_id:c.id});state.editorSource=d.source||'';render();return;}
 if(a==='invite'){b.disabled=true;const code=await cloud.rpc('ae_create_invite');document.querySelector('#invite-result').innerHTML=`<div class="notice">رمز خاص صالح لمرة واحدة لمدة ٧ أيام:<br><code dir="ltr">${esc(code)}</code></div>`;b.disabled=false;return;}

 if(a==='bank-new'||a==='bank-edit'){
  const row=a==='bank-edit'?state.bank.find(x=>x.id===b.dataset.id):null;
  const q=row?.question||{id:'b-'+crypto.randomUUID().replaceAll('-',''),prompt:'',options:['','','',''],answer:0,explanation:''};
  showModal('<h2>'+(row?'تحرير سؤال معتمد':'إضافة سؤال للبنك')+'</h2><form id="bank-form"><label class="field">المحطة<select name="station">'+[...titles,'التحدي النهائي'].map((t,i)=>'<option value="'+(i+1)+'" '+(row?.station===i+1?'selected':'')+'>'+t+'</option>').join('')+'</select></label>'+questionEditor(q,'question',0)+'<div id="bank-notice" role="status"></div><button class="btn" type="submit">حفظ السؤال سحابيًا</button></form>');
  document.querySelector('#bank-form details').open=true;
  document.querySelector('#bank-form').onsubmit=async e=>{e.preventDefault();const form=e.target;formBusy(form,true);try{const updated=structuredClone(q);for(const input of form.querySelectorAll('[data-path]')){const path=input.dataset.path.split('.').slice(1);let obj=updated;for(const k of path.slice(0,-1))obj=obj[k];obj[path.at(-1)]=input.dataset.number?Number(input.value):input.value;}await cloud.rpc('ae_bank_save',{p_source:state.bankSource,p_station:Number(new FormData(form).get('station')),p_question:updated,p_active:row?.active??true});await loadBank();modal.close();render();toast('تم حفظ السؤال في البنك. النسخ المنشورة لم تتغير.');}catch(err){document.querySelector('#bank-notice').textContent=err.message;}finally{formBusy(form,false);}};return;
 }
 if(a==='bank-toggle'){const row=state.bank.find(x=>x.id===b.dataset.id);b.disabled=true;await cloud.rpc('ae_bank_save',{p_source:state.bankSource,p_station:row.station,p_question:row.question,p_active:!row.active});await loadBank();render();toast(row.active?'تم إيقاف السؤال عن التوليد؛ يمكنك تفعيله لاحقًا.':'تم تفعيل السؤال.');return;}
 if(a==='export-content'){collectEditor();download('africa-course.json',JSON.stringify(state.editor,null,2),'application/json');return;}
 if(a==='export-reports'){const csv=[['اسم الطالب','الدرس','معرف النسخة','الدرجة من 100','الأسئلة المكتملة','آخر نشاط'],...state.reports.map(r=>[r.display_name,r.title,r.course_id,r.score,r.finished,r.last_active])].map(row=>row.map(x=>'"'+String(x).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\r\n');download('explorers-report.csv','\ufeff'+csv,'text/csv;charset=utf-8');return;}
 }catch(err){b.disabled=false;toast(err.message);}});
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function formBusy(form,busy){form.classList.toggle('busy',busy);for(const b of form.querySelectorAll('button[type=submit]'))b.disabled=busy;}
function bindForms(){const authForm=document.querySelector('#auth-form');if(authForm)authForm.onsubmit=async e=>{e.preventDefault();formBusy(authForm,true);const n=document.querySelector('#auth-notice');n.innerHTML='';try{const f=new FormData(authForm);if(state.authMode==='reset'){await cloud.reset(f.get('email'));n.innerHTML='<div class="notice">لو البريد مسجّل، ستصلك رسالة الاستعادة. تحقق أيضًا من البريد غير المرغوب.</div>';return;}if(state.authMode==='recovery'){await cloud.password(f.get('password'));await boot();render();toast('تم تغيير كلمة المرور.');return;}if(state.authMode==='signup'){if(f.get('invite'))sessionStorage.setItem('ae-pending-invite',f.get('invite'));const d=await cloud.signup(f.get('email'),f.get('password'),f.get('name'));if(!d.access_token){n.innerHTML='<div class="notice">تم إرسال طلب التسجيل. افتح رسالة تأكيد البريد، ثم ارجع وسجّل دخولك. احتفظ برمز دعوتك إن كنت معلمًا.</div>';return;}}else await cloud.login(f.get('email'),f.get('password'));await cloud.rpc('ae_me');const invite=sessionStorage.getItem('ae-pending-invite');if(invite){try{await cloud.rpc('ae_redeem_invite',{p_code:invite});sessionStorage.removeItem('ae-pending-invite');}catch(err){toast(err.message);}}await boot();if(state.authRole==='teacher'&&state.profile.role!=='teacher'){showModal('<h2>تفعيل حساب المعلم</h2><p>حسابك مسجل حاليًا كطالب. أدخل رمز الدعوة الخاص بالمعلم لتفعيل أدوات المحتوى.</p><form id="redeem-form"><label class="field">رمز الدعوة<input name="code" dir="ltr" required autocomplete="off"></label><div id="redeem-notice" role="status"></div><button class="btn" type="submit">تفعيل حساب المعلم</button></form>');document.querySelector('#redeem-form').onsubmit=async e=>{e.preventDefault();const form=e.target;formBusy(form,true);try{await cloud.rpc('ae_redeem_invite',{p_code:new FormData(form).get('code')});await boot();modal.close();render();}catch(err){document.querySelector('#redeem-notice').textContent=err.message;}finally{formBusy(form,false);}};}render();}catch(err){n.innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}finally{formBusy(authForm,false);}};
 const select=document.querySelector('#course-select');if(select)select.onchange=async e=>{try{await loadCourse(e.target.value);localStorage.setItem('ae-course',e.target.value);render();}catch(err){toast(err.message);}};
 const pf=document.querySelector('#practice-form');if(pf)pf.onsubmit=e=>{e.preventDefault();const data=new FormData(pf),cards=currentStation().cards.slice(0,5);const n=pf.dataset.order?state.practiceOrder.filter((x,i)=>x===i).length:cards.filter((c,i)=>data.get('p'+i)===c.title).length;document.querySelector('#practice-feedback').innerHTML=`<div class="feedback ${n===cards.length?'':'wrong'}">${n===cards.length?'ربط ممتاز! جاهز للتحدي.':'ربطت '+ar(n)+' من '+ar(cards.length)+' بشكل صحيح. راجع البطاقات وجرّب من جديد.'}</div>`;tone(n===cards.length);};
 const qf=document.querySelector('#quiz-form');if(qf)qf.onsubmit=async e=>{e.preventDefault();formBusy(qf,true);try{const choice=Number(new FormData(qf).get('choice'));const qs=state.view==='final'?state.course.document.final:currentStation().questions;const q=qs[state.question];if(state.preview){const right=choice===q.answer;const old=state.progress.find(a=>a.question_id===q.id);const attempts=(old?.attempts||0)+1;const points=right?(state.view==='final'?(attempts===1?5:2):(attempts===1?3:1)):0;state.feedback={correct:right,score:points,attempts,explanation:q.explanation,answer:right||attempts>=2?q.answer:null,finished:right||attempts>=2};state.progress=state.progress.filter(a=>a.question_id!==q.id).concat({question_id:q.id,station:state.view==='final'?5:state.station,attempts,correct:right,score:points,last_choice:choice});}else{state.feedback=await cloud.rpc('ae_submit',{p_id:state.course.id,p_question:q.id,p_choice:choice});state.progress=await cloud.rpc('ae_progress',{p_id:state.course.id});}tone(state.feedback.correct);render();}catch(err){document.querySelector('#quiz-error').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;formBusy(qf,false);}};
 const gf=document.querySelector('#generate-form');if(gf)gf.onsubmit=async e=>{e.preventDefault();formBusy(gf,true);const n=document.querySelector('#generate-notice');n.innerHTML='<div class="notice">يجمع الباك إند نسخة جديدة من المحتوى والأسئلة المعتمدة…</div>';try{const f=new FormData(gf);state.generationSource=f.get('source_id');const d=await cloud.generate(state.generationSource,f.get('title'),Number(f.get('focus')));state.editor=d.document;state.editorSource=d.source;state.editorId=d.id;state.teacherTab='editor';state.courses=await cloud.rpc('ae_list_courses');render();toast('نسختك اتولّدت من البنك السحابي واتحفظت كمسودة خاصة.');}catch(err){n.innerHTML='<div class="notice error">'+esc(err.message)+'</div>';}finally{formBusy(gf,false);}};
 const bs=document.querySelector('#bank-course-select');if(bs)bs.onchange=async e=>{state.bankSource=e.target.value;try{await loadBank();render();}catch(err){toast(err.message);}};
 const ef=document.querySelector('#editor-form');if(ef)ef.onsubmit=async e=>{e.preventDefault();formBusy(ef,true);try{await saveEditor();render();toast('تم حفظ المسودة سحابيًا.');}catch(err){document.querySelector('#editor-notice').innerHTML=`<div class="notice error">${esc(err.message)}</div>`;}finally{formBusy(ef,false);}};
 const search=document.querySelector('#report-search');if(search)search.oninput=e=>{for(const row of document.querySelectorAll('[data-report-row]'))row.hidden=!row.textContent.includes(e.target.value);};
}
window.addEventListener('online',()=>toast('عاد الاتصال. يمكنك متابعة الحفظ السحابي.'));window.addEventListener('offline',()=>toast('انقطع الاتصال. الإجابات الجديدة تحتاج اتصالًا لحفظها.'));
async function init(){try{const type=cloud.acceptRedirect();if(type==='recovery'){state.authMode='recovery';state.view='auth';render();return;}if(cloud.session)await boot();}catch(err){toast(err.message);state.view='auth';}render();}
init();
